<?php
declare(strict_types=1);
namespace VazinCMS\Controllers;
use PDO; use Throwable; use VazinCMS\{Access,Audit,Auth,Database,DeliveryPolicy,ReleaseChannel,Scheduler,Security,View,Webhook};

final class AdminController
{
    private function staff(): array { return Auth::requireUser(['owner','admin','support']); }
    public function team(): void
    {
        $user=Auth::requireUser(['owner']);$pdo=Database::connection();$error=null;$message=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            Security::verifyCsrf();$action=(string)($_POST['action']??'');$memberId=(int)($_POST['member_id']??0);
            if($action==='create'){
                $name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$role=(string)($_POST['role']??'support');
                if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12||!in_array($role,['admin','support'],true))$error='اطلاعات عضو تیم معتبر نیست.';
                else try{$pdo->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(:name,:email,:hash,:role,'active')")->execute(['name'=>$name,'email'=>$email,'hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role]);Audit::log('team.member_created','عضو تیم ساخته شد',(int)$user['id'],['target_id'=>$pdo->lastInsertId(),'role'=>$role]);header('Location: /admin/team');return;}catch(Throwable){$error='این ایمیل قبلاً ثبت شده است.';}
            } elseif($memberId>0){
                $check=$pdo->prepare("SELECT id,status FROM users WHERE id=:id AND role IN ('admin','support')");$check->execute(['id'=>$memberId]);$member=$check->fetch();if(!$member)$this->missing();
                if($action==='permissions'){$permissions=array_values(array_intersect((array)($_POST['permissions']??[]),array_keys(Access::definitions())));$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM staff_permissions WHERE user_id=:id')->execute(['id'=>$memberId]);$insert=$pdo->prepare('INSERT INTO staff_permissions(user_id,permission,is_granted,updated_by) VALUES(:uid,:permission,1,:owner)');foreach($permissions as $permission)$insert->execute(['uid'=>$memberId,'permission'=>$permission,'owner'=>$user['id']]);$pdo->commit();Audit::log('team.permissions_updated','دسترسی‌های عضو تیم ویرایش شد',(int)$user['id'],['target_id'=>$memberId,'permissions'=>$permissions]);$message='دسترسی‌ها ذخیره شد.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
                elseif($action==='toggle'){$new=$member['status']==='active'?'suspended':'active';$pdo->prepare('UPDATE users SET status=:status,session_version=session_version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['status'=>$new,'id'=>$memberId]);$pdo->prepare('UPDATE active_sessions SET revoked_at=CURRENT_TIMESTAMP WHERE user_id=:id AND revoked_at IS NULL')->execute(['id'=>$memberId]);Audit::log('team.status_changed','وضعیت عضو تیم تغییر کرد',(int)$user['id'],['target_id'=>$memberId,'status'=>$new]);header('Location: /admin/team?member='.$memberId);return;}
                elseif($action==='revoke'){$pdo->prepare('UPDATE users SET session_version=session_version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['id'=>$memberId]);$pdo->prepare('UPDATE active_sessions SET revoked_at=CURRENT_TIMESTAMP WHERE user_id=:id AND revoked_at IS NULL')->execute(['id'=>$memberId]);Audit::log('team.sessions_revoked','نشست‌های عضو تیم لغو شد',(int)$user['id'],['target_id'=>$memberId]);$message='تمام نشست‌های عضو تیم لغو شد.';}
            }
        }
        $staff=$pdo->query("SELECT u.id,u.name,u.email,u.role,u.status,COUNT(s.id) session_count FROM users u LEFT JOIN active_sessions s ON s.user_id=u.id AND s.revoked_at IS NULL WHERE u.role IN ('owner','admin','support') GROUP BY u.id,u.name,u.email,u.role,u.status ORDER BY CASE u.role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,u.id")->fetchAll();
        $selected=null;$selectedPermissions=[];$sessions=[];$selectedId=(int)($_GET['member']??$_POST['member_id']??0);
        if($selectedId>0){$s=$pdo->prepare("SELECT id,name,email,role,status FROM users WHERE id=:id AND role IN ('admin','support')");$s->execute(['id'=>$selectedId]);$selected=$s->fetch()?:null;if($selected){$p=$pdo->prepare('SELECT permission FROM staff_permissions WHERE user_id=:id AND is_granted=1');$p->execute(['id'=>$selectedId]);$selectedPermissions=$p->fetchAll(PDO::FETCH_COLUMN);if($selectedPermissions===[])$selectedPermissions=array_values(array_filter(array_keys(Access::definitions()),fn($permission)=>Access::allowed($selected,$permission)));$s=$pdo->prepare('SELECT ip_address,user_agent,last_seen_at,revoked_at FROM active_sessions WHERE user_id=:id ORDER BY id DESC LIMIT 20');$s->execute(['id'=>$selectedId]);$sessions=$s->fetchAll();}}
        View::render('team',compact('user','staff','selected','selectedPermissions','sessions','error','message'));
    }
    public function dashboard(): void
    {
        $user=$this->staff(); $pdo=Database::connection();
        $stats=['users'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='client'")->fetchColumn(),'services'=>(int)$pdo->query("SELECT COUNT(*) FROM services WHERE status='active'")->fetchColumn(),'orders'=>(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status IN ('pending','paid','processing')")->fetchColumn(),'tickets'=>(int)$pdo->query("SELECT COUNT(*) FROM tickets WHERE status<>'closed'")->fetchColumn()];
        $events=$pdo->query('SELECT action,description,created_at FROM audit_logs ORDER BY id DESC LIMIT 8')->fetchAll(); $releaseChannel=ReleaseChannel::stable(); View::render('dashboard',compact('user','stats','events','releaseChannel'));
    }
    public function users(): void
    {
        $user=$this->staff(); $pdo=Database::connection(); $error=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            Security::verifyCsrf(); if(!in_array($user['role'],['owner','admin'],true))$this->deny();
            $name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$role=(string)($_POST['role']??'client');$password=(string)($_POST['password']??'');
            if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12||!in_array($role,['admin','support','client'],true))$error='اطلاعات کاربر کامل یا معتبر نیست.';
            else try{$s=$pdo->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(:name,:email,:hash,:role,'active')");$s->execute(['name'=>$name,'email'=>$email,'hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role]);Audit::log('user.created','کاربر جدید ساخته شد',(int)$user['id'],['target_id'=>$pdo->lastInsertId(),'email'=>$email,'role'=>$role]);header('Location: /admin/users');return;}catch(Throwable){$error='این ایمیل قبلاً ثبت شده است.';}
        }
        $q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$role=(string)($_GET['role']??'client');$page=max(1,(int)($_GET['page']??1));$limit=20;$where=[];$params=[];
        if($q!==''){$where[]='(CAST(id AS TEXT)=:exact OR name LIKE :q OR email LIKE :q OR phone LIKE :q OR company LIKE :q)';$params['exact']=$q;$params['q']='%'.$q.'%';}
        if(in_array($status,['active','suspended','pending','closed'],true)){$where[]='status=:status';$params['status']=$status;}
        if(in_array($role,['owner','admin','support','client'],true)){$where[]='role=:role';$params['role']=$role;}
        $sql=$where?' WHERE '.implode(' AND ',$where):'';$count=$pdo->prepare('SELECT COUNT(*) FROM users'.$sql);$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$limit));$page=min($page,$pages);
        $s=$pdo->prepare('SELECT id,name,email,phone,company,role,status,created_at FROM users'.$sql.' ORDER BY id DESC LIMIT '.$limit.' OFFSET '.(($page-1)*$limit));$s->execute($params);$users=$s->fetchAll();View::render('users',compact('user','users','error','q','status','role','page','pages','total'));
    }
    public function user(int $id): void
    {
        $user=$this->staff();$pdo=Database::connection();$s=$pdo->prepare('SELECT id,name,email,phone,company,country,notes,role,status,created_at FROM users WHERE id=:id');$s->execute(['id'=>$id]);$profile=$s->fetch();if(!$profile)$this->missing();$error=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            Security::verifyCsrf();if(!in_array($user['role'],['owner','admin'],true))$this->deny();$action=(string)($_POST['action']??'save');
            if($action==='status'){$new=(string)($_POST['status']??'');if((int)$profile['id']===(int)$user['id']||!in_array($new,['active','suspended','pending','closed'],true))$error='این تغییر وضعیت مجاز نیست.';else{$pdo->prepare('UPDATE users SET status=:status,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['status'=>$new,'id'=>$id]);Audit::log('user.status_changed','وضعیت حساب تغییر کرد',(int)$user['id'],['target_id'=>$id,'from'=>$profile['status'],'to'=>$new]);header('Location: /admin/users/'.$id);return;}}
            elseif($action==='wallet_adjust'){
                $walletId=(int)($_POST['wallet_id']??0);$kind=(string)($_POST['kind']??'credit');$amount=round((float)($_POST['amount']??0),2);$description=trim((string)($_POST['description']??''));$requestKey=trim((string)($_POST['request_key']??''));
                if($walletId<1||!in_array($kind,['credit','debit'],true)||$amount<=0||mb_strlen($description)<4||!preg_match('/^[a-f0-9]{32}$/',$requestKey))$error='کیف پول، مبلغ یا دلیل تغییر معتبر نیست.';
                else{$pdo->beginTransaction();try{$lock=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='pgsql'?' FOR UPDATE':'';$ws=$pdo->prepare('SELECT id,user_id,currency,balance FROM wallets WHERE id=:wallet AND user_id=:uid'.$lock);$ws->execute(['wallet'=>$walletId,'uid'=>$id]);$wallet=$ws->fetch();if(!$wallet)throw new \RuntimeException('کیف پول انتخاب‌شده متعلق به این مشتری نیست.');$reference='ADMIN-'.$requestKey;$duplicate=$pdo->prepare('SELECT id FROM wallet_transactions WHERE reference=:reference');$duplicate->execute(['reference'=>$reference]);if($duplicate->fetchColumn())throw new \RuntimeException('این درخواست قبلاً ثبت شده است؛ صفحه را تازه‌سازی کنید.');$before=round((float)$wallet['balance'],2);$after=round($before+($kind==='credit'?$amount:-$amount),2);if($after<0)throw new \RuntimeException('موجودی کیف پول کافی نیست.');$pdo->prepare('UPDATE wallets SET balance=:balance,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['balance'=>$after,'id'=>$walletId]);$pdo->prepare('INSERT INTO wallet_transactions(wallet_id,user_id,type,amount,balance_after,currency,reference,description,created_by) VALUES(:wallet,:uid,:type,:amount,:balance,:currency,:reference,:description,:staff)')->execute(['wallet'=>$walletId,'uid'=>$id,'type'=>$kind,'amount'=>$amount,'balance'=>$after,'currency'=>$wallet['currency'],'reference'=>$reference,'description'=>$description,'staff'=>$user['id']]);$pdo->commit();Audit::log('customer.wallet_adjusted','موجودی مشتری از پروفایل اصلاح شد',(int)$user['id'],['target_id'=>$id,'wallet_id'=>$walletId,'type'=>$kind,'amount'=>$amount,'balance_before'=>$before,'balance_after'=>$after,'currency'=>$wallet['currency'],'reason'=>$description]);header('Location: /admin/users/'.$id.'?wallet=updated');return;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof \RuntimeException?$e->getMessage():'تغییر موجودی ثبت نشد.';}}
            } else{$data=['name'=>trim((string)($_POST['name']??'')),'email'=>strtolower(trim((string)($_POST['email']??''))),'phone'=>trim((string)($_POST['phone']??'')),'company'=>trim((string)($_POST['company']??'')),'country'=>trim((string)($_POST['country']??'')),'notes'=>trim((string)($_POST['notes']??'')),'id'=>$id];if(mb_strlen($data['name'])<2||!filter_var($data['email'],FILTER_VALIDATE_EMAIL))$error='نام یا ایمیل معتبر نیست.';else try{$pdo->prepare('UPDATE users SET name=:name,email=:email,phone=:phone,company=:company,country=:country,notes=:notes,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute($data);Audit::log('user.updated','پروفایل کاربر ویرایش شد',(int)$user['id'],['target_id'=>$id]);header('Location: /admin/users/'.$id);return;}catch(Throwable){$error='ایمیل تکراری است.';}}
        }
        $t=$pdo->prepare('SELECT id,subject,status,priority,updated_at FROM tickets WHERE user_id=:id ORDER BY updated_at DESC LIMIT 10');$t->execute(['id'=>$id]);$tickets=$t->fetchAll();
        $s=$pdo->prepare('SELECT id,name,status,identifier,expires_at FROM services WHERE user_id=:id ORDER BY id DESC LIMIT 10');$s->execute(['id'=>$id]);$services=$s->fetchAll();
        $s=$pdo->prepare('SELECT id,order_number,status,amount,currency,created_at FROM orders WHERE user_id=:id ORDER BY id DESC LIMIT 10');$s->execute(['id'=>$id]);$orders=$s->fetchAll();
        $s=$pdo->prepare('SELECT id,invoice_number,status,total,currency,due_at FROM invoices WHERE user_id=:id ORDER BY id DESC LIMIT 10');$s->execute(['id'=>$id]);$invoices=$s->fetchAll();
        $s=$pdo->prepare('SELECT id,currency,balance,updated_at FROM wallets WHERE user_id=:id ORDER BY currency');$s->execute(['id'=>$id]);$wallets=$s->fetchAll();
        $s=$pdo->prepare('SELECT wt.id,wt.wallet_id,wt.type,wt.amount,wt.balance_after,wt.currency,wt.description,wt.reference,wt.created_at,u.name staff_name FROM wallet_transactions wt LEFT JOIN users u ON u.id=wt.created_by WHERE wt.user_id=:id ORDER BY wt.id DESC LIMIT 20');$s->execute(['id'=>$id]);$walletTransactions=$s->fetchAll();
        $summary=['services'=>count($services),'orders'=>(int)$pdo->query('SELECT COUNT(*) FROM orders WHERE user_id='.(int)$id)->fetchColumn(),'invoices'=>(int)$pdo->query('SELECT COUNT(*) FROM invoices WHERE user_id='.(int)$id)->fetchColumn(),'tickets'=>(int)$pdo->query('SELECT COUNT(*) FROM tickets WHERE user_id='.(int)$id)->fetchColumn()];
        $walletUpdated=($_GET['wallet']??'')==='updated';$walletRequestKey=bin2hex(random_bytes(16));
        View::render('user-profile',compact('user','profile','tickets','services','orders','invoices','wallets','walletTransactions','walletUpdated','walletRequestKey','summary','error'));
    }
    public function products(): void
    {
        $user=Auth::requireUser(['owner','admin']);$pdo=Database::connection();$error=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$slug=strtolower(trim((string)($_POST['slug']??'')));$type=(string)($_POST['type']??'service');$price=(float)($_POST['price_amount']??0);$currency=strtoupper(trim((string)($_POST['currency']??'RUB')));$cycle=(string)($_POST['billing_cycle']??'monthly');$description=trim((string)($_POST['description']??''));$active=isset($_POST['is_active'])?1:0;if(mb_strlen($name)<2||!preg_match('/^[a-z0-9][a-z0-9-]{1,99}$/',$slug)||$price<0||!preg_match('/^[A-Z]{3,8}$/',$currency)||!in_array($cycle,['one_time','monthly','quarterly','yearly'],true))$error='اطلاعات محصول معتبر نیست.';else try{$data=['slug'=>$slug,'name'=>$name,'type'=>$type,'description'=>$description,'price'=>$price,'currency'=>$currency,'cycle'=>$cycle,'active'=>$active];if($id>0){$data['id']=$id;$pdo->prepare('UPDATE products SET slug=:slug,name=:name,type=:type,description=:description,price_amount=:price,currency=:currency,billing_cycle=:cycle,is_active=:active,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute($data);$action='product.updated';}else{$pdo->prepare("INSERT INTO products(slug,name,type,status,description,price_amount,currency,billing_cycle,is_active) VALUES(:slug,:name,:type,'detached',:description,:price,:currency,:cycle,:active)")->execute($data);$id=(int)$pdo->lastInsertId();$action='product.created';}Audit::log($action,'محصول ذخیره شد',(int)$user['id'],['product_id'=>$id]);header('Location: /admin/products');return;}catch(Throwable){$error='شناسه محصول تکراری یا اطلاعات نامعتبر است.';}}
        $products=$pdo->query('SELECT id,slug,name,type,status,price_amount,currency,billing_cycle,is_active,current_version FROM products ORDER BY id DESC')->fetchAll();View::render('products',compact('user','products','error'));
    }
    public function orders(): void
    {
        $user=$this->staff();$pdo=Database::connection();$error=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            Security::verifyCsrf();$uid=(int)($_POST['user_id']??0);$pid=(int)($_POST['product_id']??0);$code=strtoupper(trim((string)($_POST['discount_code']??'')));
            $p=$pdo->prepare('SELECT id,name,price_amount,currency FROM products WHERE id=:id AND is_active=1');$p->execute(['id'=>$pid]);$product=$p->fetch();
            if($uid<1||!$product)$error='مشتری یا محصول معتبر نیست.';else{$pdo->beginTransaction();try{
                $subtotal=round((float)$product['price_amount'],2);$discount=0.0;$discountId=null;
                if($code!==''){$lock=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='pgsql'?' FOR UPDATE':'';$d=$pdo->prepare("SELECT * FROM discounts WHERE code=:code AND is_active=1 AND (starts_at IS NULL OR starts_at<=CURRENT_TIMESTAMP) AND (expires_at IS NULL OR expires_at>=CURRENT_TIMESTAMP)".$lock);$d->execute(['code'=>$code]);$coupon=$d->fetch();if(!$coupon||($coupon['currency']&&$coupon['currency']!==$product['currency'])||($coupon['max_uses']!==null&&(int)$coupon['used_count']>=(int)$coupon['max_uses'])||$subtotal<(float)$coupon['minimum_amount'])throw new \RuntimeException('کد تخفیف معتبر نیست یا شرایط استفاده را ندارد.');$discount=$coupon['type']==='percent'?round($subtotal*min(100,(float)$coupon['value'])/100,2):min($subtotal,round((float)$coupon['value'],2));$discountId=(int)$coupon['id'];}
                $amount=max(0,round($subtotal-$discount,2));$number='VO-'.gmdate('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
                $s=$pdo->prepare("INSERT INTO orders(order_number,user_id,product_id,product_name,subtotal,discount_amount,discount_id,discount_code,amount,currency,status,notes,created_by) VALUES(:num,:uid,:pid,:name,:subtotal,:discount,:discount_id,:code,:amount,:currency,'pending',:notes,:staff)");$s->execute(['num'=>$number,'uid'=>$uid,'pid'=>$pid,'name'=>$product['name'],'subtotal'=>$subtotal,'discount'=>$discount,'discount_id'=>$discountId,'code'=>$discountId?$code:null,'amount'=>$amount,'currency'=>$product['currency'],'notes'=>trim((string)($_POST['notes']??'')),'staff'=>$user['id']]);$id=(int)$pdo->lastInsertId();
                if($discountId){$pdo->prepare('UPDATE discounts SET used_count=used_count+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['id'=>$discountId]);$pdo->prepare('INSERT INTO discount_redemptions(discount_id,order_id,user_id,code,discount_amount,currency) VALUES(:discount,:order,:user,:code,:amount,:currency)')->execute(['discount'=>$discountId,'order'=>$id,'user'=>$uid,'code'=>$code,'amount'=>$discount,'currency'=>$product['currency']]);}
                $pdo->commit();Audit::log('order.created','سفارش جدید ساخته شد',(int)$user['id'],['order_id'=>$id,'number'=>$number,'discount'=>$discount,'discount_code'=>$discountId?$code:null]);header('Location: /admin/orders/'.$id);return;
            }catch(\RuntimeException $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
        }
        $status=(string)($_GET['status']??'');$where='';$params=[];if(in_array($status,['pending','paid','processing','completed','cancelled','refunded'],true)){$where=' WHERE o.status=:status';$params['status']=$status;}$s=$pdo->prepare('SELECT o.*,u.name customer FROM orders o JOIN users u ON u.id=o.user_id'.$where.' ORDER BY o.id DESC LIMIT 200');$s->execute($params);$orders=$s->fetchAll();$clients=$pdo->query("SELECT id,name,email FROM users WHERE role='client' AND status='active' ORDER BY name")->fetchAll();$products=$pdo->query('SELECT id,name,price_amount,currency FROM products WHERE is_active=1 ORDER BY name')->fetchAll();View::render('orders',compact('user','orders','clients','products','error','status'));
    }
    public function order(int $id): void
    {
        $user=$this->staff();$pdo=Database::connection();$s=$pdo->prepare('SELECT o.*,u.name customer,u.email FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=:id');$s->execute(['id'=>$id]);$order=$s->fetch();if(!$order)$this->missing();
        if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$status=(string)($_POST['status']??'');if(!in_array($status,['pending','paid','processing','completed','cancelled','refunded'],true))$this->deny();$pdo->beginTransaction();try{$pdo->prepare('UPDATE orders SET status=:status,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['status'=>$status,'id'=>$id]);if($status==='completed'){$check=$pdo->prepare('SELECT id FROM services WHERE order_id=:id');$check->execute(['id'=>$id]);if(!$check->fetchColumn())$pdo->prepare("INSERT INTO services(user_id,product_id,order_id,name,status,started_at) VALUES(:uid,:pid,:oid,:name,'active',CURRENT_TIMESTAMP)")->execute(['uid'=>$order['user_id'],'pid'=>$order['product_id'],'oid'=>$id,'name'=>$order['product_name']]);}$pdo->commit();Audit::log('order.status_changed','وضعیت سفارش تغییر کرد',(int)$user['id'],['order_id'=>$id,'from'=>$order['status'],'to'=>$status]);header('Location: /admin/orders/'.$id);return;}catch(Throwable $e){$pdo->rollBack();throw $e;}}
        $v=$pdo->prepare('SELECT id,name,status,identifier,expires_at FROM services WHERE order_id=:id');$v->execute(['id'=>$id]);$service=$v->fetch();View::render('order',compact('user','order','service'));
    }
    public function discounts(): void
    {
        $user=Auth::requireUser(['owner','admin']);$pdo=Database::connection();$error=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
            if($action==='toggle'){$pdo->prepare('UPDATE discounts SET is_active=CASE WHEN is_active=1 THEN 0 ELSE 1 END,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['id'=>$id]);Audit::log('discount.toggled','وضعیت کد تخفیف تغییر کرد',(int)$user['id'],['discount_id'=>$id]);header('Location: /admin/discounts');return;}
