                $pdo->commit();Audit::log('renewal.invoice_created','فاکتور تمدید سرویس ساخته شد',(int)$user['id'],['service_id'=>$serviceId,'invoice_id'=>$invoiceId]);header('Location: /admin/invoices/'.$invoiceId);return;
            }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof \RuntimeException?$e->getMessage():'فاکتور تمدید قبلاً ساخته شده یا عملیات ناموفق بود.';}
        }
