        $services=$pdo->query("SELECT s.*,u.name customer,u.email,r.invoice_id renewal_invoice_id FROM services s JOIN users u ON u.id=s.user_id LEFT JOIN service_renewals r ON r.service_id=s.id AND r.renewal_key=(CAST(s.id AS VARCHAR)||'-'||substr(CAST(s.expires_at AS VARCHAR),1,10)) WHERE s.status IN ('active','expired') AND s.expires_at IS NOT NULL AND s.expires_at <= $modifier ORDER BY s.expires_at ASC LIMIT 300")->fetchAll();
