    public function invoice(int $id): void
    {
        $user=$this->staff();$pdo=Database::connection();$s=$pdo->prepare('SELECT i.*,u.name customer,u.email,o.order_number,COALESCE(SUM(p.amount) FILTER (WHERE p.status=\'confirmed\'),0) paid_amount FROM invoices i JOIN users u ON u.id=i.user_id LEFT JOIN orders o ON o.id=i.order_id LEFT JOIN payments p ON p.invoice_id=i.id WHERE i.id=:id GROUP BY i.id,u.name,u.email,o.order_number');$s->execute(['id'=>$id]);$invoice=$s->fetch();if(!$invoice)$this->missing();$error=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$action=(string)($_POST['action']??'payment');if($action==='cancel'){if(!in_array($user['role'],['owner','admin'],true))$this->deny();$pdo->prepare("UPDATE invoices SET status='cancelled',updated_at=CURRENT_TIMESTAMP WHERE id=:id AND status<>'paid'")->execute(['id'=>$id]);Audit::log('invoice.cancelled','فاکتور لغو شد',(int)$user['id'],['invoice_id'=>$id]);}else{$amount=(float)($_POST['amount']??0);$balance=max(0,(float)$invoice['total']-(float)$invoice['paid_amount']);$method=trim((string)($_POST['method']??''));$reference=trim((string)($_POST['reference']??''));if($amount<=0||$amount>$balance||$balance<=0||mb_strlen($method)<2||in_array($invoice['status'],['cancelled','refunded'],true))$error='مبلغ یا روش پرداخت معتبر نیست.';else{$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO payments(invoice_id,user_id,amount,currency,method,reference,status,received_by) VALUES(:invoice,:uid,:amount,:currency,:method,:reference,'confirmed',:staff)")->execute(['invoice'=>$id,'uid'=>$invoice['user_id'],'amount'=>$amount,'currency'=>$invoice['currency'],'method'=>$method,'reference'=>$reference?:null,'staff'=>$user['id']]);$paid=(float)$invoice['paid_amount']+$amount;$status=$paid>=(float)$invoice['total']?'paid':'partial';$pdo->prepare('UPDATE invoices SET status=:status,paid_at=CASE WHEN :status2=\'paid\' THEN CURRENT_TIMESTAMP ELSE paid_at END,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['status'=>$status,'status2'=>$status,'id'=>$id]);if($status==='paid'&&$invoice['order_id'])$pdo->prepare("UPDATE orders SET status='paid',updated_at=CURRENT_TIMESTAMP WHERE id=:id AND status='pending'")->execute(['id'=>$invoice['order_id']]);$pdo->commit();Audit::log('payment.recorded','پرداخت ثبت شد',(int)$user['id'],['invoice_id'=>$id,'amount'=>$amount,'currency'=>$invoice['currency']]);header('Location: /admin/invoices/'.$id);return;}catch(Throwable $e){$pdo->rollBack();throw $e;}}}if(!$error){header('Location: /admin/invoices/'.$id);return;}}
        $p=$pdo->prepare('SELECT p.*,u.name receiver FROM payments p LEFT JOIN users u ON u.id=p.received_by WHERE p.invoice_id=:id ORDER BY p.id DESC');$p->execute(['id'=>$id]);$payments=$p->fetchAll();View::render('invoice',compact('user','invoice','payments','error'));
    }
