    public function wallet(int $id): void
    {
        $user=Auth::requireUser(['owner','admin']);$pdo=Database::connection();$error=null;
        $s=$pdo->prepare('SELECT w.*,u.name customer,u.email FROM wallets w JOIN users u ON u.id=w.user_id WHERE w.id=:id');$s->execute(['id'=>$id]);$wallet=$s->fetch();if(!$wallet)$this->missing();
        if($_SERVER['REQUEST_METHOD']==='POST'){
            Security::verifyCsrf();$action=(string)($_POST['action']??'adjust');
            if($action==='pay_invoice'){$invoiceId=(int)($_POST['invoice_id']??0);$pdo->beginTransaction();try{
                $lock=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='pgsql'?' FOR UPDATE':'';
                $ws=$pdo->prepare('SELECT * FROM wallets WHERE id=:id'.$lock);$ws->execute(['id'=>$id]);$current=$ws->fetch();
                $is=$pdo->prepare('SELECT * FROM invoices WHERE id=:iid AND user_id=:uid'.$lock);$is->execute(['iid'=>$invoiceId,'uid'=>$wallet['user_id']]);$invoice=$is->fetch();
                if($invoice){$ps=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM payments WHERE invoice_id=:id AND status='confirmed'");$ps->execute(['id'=>$invoiceId]);$invoice['paid_amount']=$ps->fetchColumn();}
                $due=$invoice?round((float)$invoice['total']-(float)$invoice['paid_amount'],2):0.0;
                if(!$invoice||$invoice['currency']!==$current['currency']||$due<=0||in_array($invoice['status'],['paid','cancelled','refunded'],true)||round((float)$current['balance'],2)<$due)throw new \RuntimeException('موجودی یا فاکتور برای پرداخت معتبر نیست.');
                $reference='WALLET-'.$id.'-'.strtoupper(bin2hex(random_bytes(4)));
                $pdo->prepare('UPDATE wallets SET balance=balance-:amount,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['amount'=>$due,'id'=>$id]);
                $pdo->prepare("INSERT INTO wallet_transactions(wallet_id,user_id,type,amount,balance_after,currency,reference,description,created_by) VALUES(:wallet,:uid,'debit',:amount,:balance,:currency,:reference,:description,:staff)")->execute(['wallet'=>$id,'uid'=>$wallet['user_id'],'amount'=>$due,'balance'=>round((float)$current['balance']-$due,2),'currency'=>$current['currency'],'reference'=>$reference,'description'=>'پرداخت فاکتور '.$invoice['invoice_number'],'staff'=>$user['id']]);
                $pdo->prepare("INSERT INTO payments(invoice_id,user_id,amount,currency,method,reference,status,received_by) VALUES(:invoice,:uid,:amount,:currency,'wallet',:reference,'confirmed',:staff)")->execute(['invoice'=>$invoiceId,'uid'=>$wallet['user_id'],'amount'=>$due,'currency'=>$current['currency'],'reference'=>$reference,'staff'=>$user['id']]);
                $pdo->prepare("UPDATE invoices SET status='paid',paid_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=:id")->execute(['id'=>$invoiceId]);if($invoice['order_id'])$pdo->prepare("UPDATE orders SET status='paid',updated_at=CURRENT_TIMESTAMP WHERE id=:id AND status='pending'")->execute(['id'=>$invoice['order_id']]);
                $pdo->commit();Audit::log('wallet.invoice_paid','فاکتور از کیف پول پرداخت شد',(int)$user['id'],['wallet_id'=>$id,'invoice_id'=>$invoiceId,'amount'=>$due,'currency'=>$current['currency']]);header('Location: /admin/wallets/'.$id);return;
            }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof \RuntimeException?$e->getMessage():'پرداخت انجام نشد.';}}
            else{$kind=(string)($_POST['kind']??'credit');$amount=round((float)($_POST['amount']??0),2);$description=trim((string)($_POST['description']??''));$reference=trim((string)($_POST['reference']??''));if(!in_array($kind,['credit','debit'],true)||$amount<=0||mb_strlen($description)<2)$error='مبلغ و توضیح معتبر لازم است.';else{$pdo->beginTransaction();try{$lock=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='pgsql'?' FOR UPDATE':'';$ws=$pdo->prepare('SELECT balance FROM wallets WHERE id=:id'.$lock);$ws->execute(['id'=>$id]);$before=(float)$ws->fetchColumn();$after=round($before+($kind==='credit'?$amount:-$amount),2);if($after<0)throw new \RuntimeException('موجودی کیف پول کافی نیست.');$pdo->prepare('UPDATE wallets SET balance=:balance,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['balance'=>$after,'id'=>$id]);$pdo->prepare('INSERT INTO wallet_transactions(wallet_id,user_id,type,amount,balance_after,currency,reference,description,created_by) VALUES(:wallet,:uid,:type,:amount,:balance,:currency,:reference,:description,:staff)')->execute(['wallet'=>$id,'uid'=>$wallet['user_id'],'type'=>$kind,'amount'=>$amount,'balance'=>$after,'currency'=>$wallet['currency'],'reference'=>$reference?:null,'description'=>$description,'staff'=>$user['id']]);$pdo->commit();Audit::log('wallet.adjusted','موجودی کیف پول اصلاح شد',(int)$user['id'],['wallet_id'=>$id,'type'=>$kind,'amount'=>$amount,'currency'=>$wallet['currency']]);header('Location: /admin/wallets/'.$id);return;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof \RuntimeException?$e->getMessage():'تراکنش ثبت نشد.';}}}
        }
        $t=$pdo->prepare('SELECT wt.*,u.name staff_name FROM wallet_transactions wt LEFT JOIN users u ON u.id=wt.created_by WHERE wt.wallet_id=:id ORDER BY wt.id DESC LIMIT 200');$t->execute(['id'=>$id]);$transactions=$t->fetchAll();
        $i=$pdo->prepare("SELECT i.id,i.invoice_number,i.total,i.currency,i.status,COALESCE(SUM(CASE WHEN p.status='confirmed' THEN p.amount ELSE 0 END),0) paid_amount FROM invoices i LEFT JOIN payments p ON p.invoice_id=i.id WHERE i.user_id=:uid AND i.currency=:currency AND i.status IN ('unpaid','partial') GROUP BY i.id ORDER BY i.id DESC");$i->execute(['uid'=>$wallet['user_id'],'currency'=>$wallet['currency']]);$invoices=$i->fetchAll();
        View::render('wallet',compact('user','wallet','transactions','invoices','error'));
    }
    public function notifications(): void
    {
        $user=$this->staff();$pdo=Database::connection();$error=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            Security::verifyCsrf();$action=(string)($_POST['action']??'');
            if($action==='generate'){
                $days=max(0,min(90,(int)($_POST['days']??7)));$limit=date('Y-m-d 23:59:59',strtotime('+'.$days.' days'));$created=0;
                $s=$pdo->prepare("SELECT i.id,i.invoice_number,i.user_id,i.total,i.currency,i.due_at,u.name FROM invoices i JOIN users u ON u.id=i.user_id WHERE i.status IN ('unpaid','partial') AND i.due_at IS NOT NULL AND i.due_at<=:lim");$s->execute(['lim'=>$limit]);
                foreach($s->fetchAll() as $row){$key='invoice-due-'.$row['id'].'-'.substr((string)$row['due_at'],0,10);try{$pdo->prepare("INSERT INTO notifications(user_id,channel,event_type,dedupe_key,subject,body,created_by) VALUES(:uid,'email','invoice_due',:key,:subject,:body,:staff)")->execute(['uid'=>$row['user_id'],'key'=>$key,'subject'=>'یادآوری فاکتور '.$row['invoice_number'],'body'=>'فاکتور '.$row['invoice_number'].' به مبلغ '.$row['total'].' '.$row['currency'].' سررسید شده یا نزدیک سررسید است.','staff'=>$user['id']]);$created++;}catch(Throwable){}}
                $s=$pdo->prepare("SELECT s.id,s.name,s.user_id,s.expires_at,u.name customer FROM services s JOIN users u ON u.id=s.user_id WHERE s.status='active' AND s.expires_at IS NOT NULL AND s.expires_at<=:lim");$s->execute(['lim'=>$limit]);
                foreach($s->fetchAll() as $row){$key='service-expiry-'.$row['id'].'-'.substr((string)$row['expires_at'],0,10);try{$pdo->prepare("INSERT INTO notifications(user_id,channel,event_type,dedupe_key,subject,body,created_by) VALUES(:uid,'email','service_expiry',:key,:subject,:body,:staff)")->execute(['uid'=>$row['user_id'],'key'=>$key,'subject'=>'یادآوری تمدید '.$row['name'],'body'=>'سرویس '.$row['name'].' در تاریخ '.substr((string)$row['expires_at'],0,10).' منقضی می‌شود.','staff'=>$user['id']]);$created++;}catch(Throwable){}}
                Audit::log('notifications.generated','اعلان‌های سررسید ساخته شد',(int)$user['id'],['created'=>$created,'days'=>$days]);header('Location: /admin/notifications');return;
            }
            if($action==='create'){$uid=(int)($_POST['user_id']??0);$subject=trim((string)($_POST['subject']??''));$body=trim((string)($_POST['body']??''));if($uid<1||mb_strlen($subject)<3||mb_strlen($body)<2)$error='مشتری، عنوان و متن معتبر لازم است.';else{$key='manual-'.$uid.'-'.bin2hex(random_bytes(8));$pdo->prepare("INSERT INTO notifications(user_id,channel,event_type,dedupe_key,subject,body,created_by) VALUES(:uid,'email','manual',:key,:subject,:body,:staff)")->execute(['uid'=>$uid,'key'=>$key,'subject'=>$subject,'body'=>$body,'staff'=>$user['id']]);Audit::log('notification.created','اعلان دستی ساخته شد',(int)$user['id'],['user_id'=>$uid]);header('Location: /admin/notifications');return;}}
            if($action==='mark'){$id=(int)($_POST['id']??0);$result=(string)($_POST['result']??'');if($id<1||!in_array($result,['sent','cancelled'],true))$this->deny();$sql=$result==='sent'?"UPDATE notifications SET status='sent',sent_at=CURRENT_TIMESTAMP,attempts=attempts+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND status='pending'":"UPDATE notifications SET status='cancelled',updated_at=CURRENT_TIMESTAMP WHERE id=:id AND status='pending'";$pdo->prepare($sql)->execute(['id'=>$id]);Audit::log('notification.status_changed','وضعیت اعلان تغییر کرد',(int)$user['id'],['notification_id'=>$id,'status'=>$result]);header('Location: /admin/notifications');return;}
        }
        $status=(string)($_GET['status']??'');$where='';$params=[];if(in_array($status,['pending','sent','failed','cancelled'],true)){$where=' WHERE n.status=:status';$params['status']=$status;}$s=$pdo->prepare('SELECT n.*,u.name customer,u.email FROM notifications n JOIN users u ON u.id=n.user_id'.$where.' ORDER BY n.scheduled_at DESC,n.id DESC LIMIT 300');$s->execute($params);$notifications=$s->fetchAll();$clients=$pdo->query("SELECT id,name,email FROM users WHERE role='client' AND status<>'closed' ORDER BY name")->fetchAll();View::render('notifications',compact('user','notifications','clients','status','error'));
    }
