    public function integrations(): void
    {
        $user=Auth::requireUser(['owner']);$pdo=Database::connection();$error=null;$newToken=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            Security::verifyCsrf();$action=(string)($_POST['action']??'create');
            if($action==='revoke'){$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE api_tokens SET revoked_at=CURRENT_TIMESTAMP WHERE id=:id AND revoked_at IS NULL')->execute(['id'=>$id]);Audit::log('api_token.revoked','کلید اتصال لغو شد',(int)$user['id'],['token_id'=>$id]);header('Location: /admin/integrations');return;}
            $name=trim((string)($_POST['name']??''));$scopes=array_values(array_intersect((array)($_POST['scopes']??[]),['read','billing','wallet','services','modules','customers','orders','content']));$expires=trim((string)($_POST['expires_at']??''));
            if($expires!==''&&strtotime($expires)===false)$error='تاریخ انقضا معتبر نیست.';elseif(mb_strlen($name)<3||$scopes===[])$error='نام و حداقل یک دسترسی معتبر لازم است.';else{$secret='vo_live_'.bin2hex(random_bytes(24));$prefix=substr($secret,0,16);$stmt=$pdo->prepare('INSERT INTO api_tokens(name,token_prefix,token_hash,scopes,expires_at,created_by) VALUES(:name,:prefix,:hash,:scopes,:expires,:uid)');$stmt->execute(['name'=>$name,'prefix'=>$prefix,'hash'=>hash('sha256',$secret),'scopes'=>json_encode($scopes,JSON_UNESCAPED_SLASHES),'expires'=>$expires!==''?date('Y-m-d H:i:s',strtotime($expires)):null,'uid'=>$user['id']]);$id=(int)$pdo->lastInsertId();Audit::log('api_token.created','کلید اتصال ساخته شد',(int)$user['id'],['token_id'=>$id,'name'=>$name,'scopes'=>$scopes]);$newToken=$secret;}
        }
        $tokens=$pdo->query('SELECT id,name,token_prefix,scopes,last_used_at,expires_at,revoked_at,created_at FROM api_tokens ORDER BY id DESC')->fetchAll();$logs=$pdo->query('SELECT l.*,t.name token_name,t.token_prefix FROM api_request_logs l LEFT JOIN api_tokens t ON t.id=l.token_id ORDER BY l.id DESC LIMIT 100')->fetchAll();View::render('integrations',compact('user','tokens','logs','error','newToken'));
    }
