    public function webhooks(): void
    {
        $user=Auth::requireUser(['owner']);$pdo=Database::connection();$error=null;$newSecret=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            Security::verifyCsrf();$action=(string)($_POST['action']??'create');$id=(int)($_POST['id']??0);
            if($action==='toggle'){$pdo->prepare('UPDATE webhook_endpoints SET is_active=CASE WHEN is_active=1 THEN 0 ELSE 1 END,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['id'=>$id]);Audit::log('webhook.toggled','وضعیت Webhook تغییر کرد',(int)$user['id'],['webhook_id'=>$id]);header('Location: /admin/webhooks');return;}
            if($action==='retry'){$delivery=(int)($_POST['delivery_id']??0);try{Webhook::retry($delivery);Audit::log('webhook.retried','ارسال Webhook دوباره در صف قرار گرفت',(int)$user['id'],['delivery_id'=>$delivery]);}catch(Throwable $e){$error=$e->getMessage();}if(!$error){header('Location: /admin/webhooks');return;}}
            if($action==='test'){try{Webhook::enqueue('webhook.test',['message'=>'Vazin Online webhook test','created_at'=>gmdate('c')],$id?:null);Audit::log('webhook.test_queued','Webhook آزمایشی در صف قرار گرفت',(int)$user['id'],['webhook_id'=>$id]);header('Location: /admin/webhooks');return;}catch(Throwable $e){$error=$e->getMessage();}}
            if($action==='create'){$name=trim((string)($_POST['name']??''));$url=trim((string)($_POST['url']??''));$events=array_values(array_intersect((array)($_POST['events']??[]),Webhook::events()));
                if(mb_strlen($name)<3||$events===[])$error='نام و حداقل یک رویداد معتبر لازم است.';else try{Webhook::validateUrl($url);$secret='whsec_'.bin2hex(random_bytes(24));$s=$pdo->prepare('INSERT INTO webhook_endpoints(name,url,secret_hash,secret_encrypted,events,created_by) VALUES(:name,:url,:hash,:secret,:events,:uid)');$s->execute(['name'=>$name,'url'=>$url,'hash'=>hash('sha256',$secret),'secret'=>Webhook::protect($secret),'events'=>json_encode($events,JSON_UNESCAPED_SLASHES),'uid'=>$user['id']]);$newSecret=$secret;Audit::log('webhook.created','مقصد Webhook ساخته شد',(int)$user['id'],['webhook_id'=>$pdo->lastInsertId(),'name'=>$name,'events'=>$events]);}catch(Throwable $e){$error=$e->getMessage();}}
        }
        $endpoints=$pdo->query('SELECT id,name,url,events,is_active,last_success_at,last_failure_at,created_at FROM webhook_endpoints ORDER BY id DESC')->fetchAll();$deliveries=$pdo->query('SELECT d.*,e.name endpoint_name FROM webhook_deliveries d JOIN webhook_endpoints e ON e.id=d.endpoint_id ORDER BY d.id DESC LIMIT 150')->fetchAll();$externalDeliveryEnabled=DeliveryPolicy::externalEnabled();View::render('webhooks',compact('user','endpoints','deliveries','error','newSecret','externalDeliveryEnabled'));
    }
    public function scheduler(): void
    {
        $user=Auth::requireUser(['owner']);$pdo=Database::connection();$error=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            Security::verifyCsrf();$action=(string)($_POST['action']??'create');$id=(int)($_POST['id']??0);
            if($action==='toggle'){$pdo->prepare('UPDATE scheduled_tasks SET is_active=CASE WHEN is_active=1 THEN 0 ELSE 1 END,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['id'=>$id]);Audit::log('scheduler.toggled','وضعیت وظیفه زمان‌بندی تغییر کرد',(int)$user['id'],['task_id'=>$id]);header('Location: /admin/scheduler');return;}
            if($action==='run'){try{$result=Scheduler::runDue($id);Audit::log('scheduler.manual_run','وظیفه زمان‌بندی دستی اجرا شد',(int)$user['id'],['task_id'=>$id,'result'=>$result]);}catch(Throwable $e){$error=$e->getMessage();}if(!$error){header('Location: /admin/scheduler');return;}}
            if($action==='create'){$name=trim((string)($_POST['name']??''));$type=(string)($_POST['task_type']??'');$minutes=(int)($_POST['interval_minutes']??60);$retention=max(30,min(3650,(int)($_POST['retention_days']??365)));
                if(mb_strlen($name)<3||!array_key_exists($type,Scheduler::types())||$minutes<1||$minutes>525600)$error='اطلاعات وظیفه معتبر نیست.';else{$config=$type==='audit_cleanup'?['retention_days'=>$retention]:[];$s=$pdo->prepare('INSERT INTO scheduled_tasks(name,task_type,interval_minutes,config,created_by) VALUES(:name,:type,:minutes,:config,:uid)');$s->execute(['name'=>$name,'type'=>$type,'minutes'=>$minutes,'config'=>json_encode($config,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'uid'=>$user['id']]);Audit::log('scheduler.created','وظیفه زمان‌بندی ساخته شد',(int)$user['id'],['task_id'=>$pdo->lastInsertId(),'type'=>$type,'interval_minutes'=>$minutes]);header('Location: /admin/scheduler');return;}
            }
        }
        $tasks=$pdo->query('SELECT * FROM scheduled_tasks ORDER BY id DESC')->fetchAll();$activeCount=count(array_filter($tasks,static fn(array $t):bool=>(bool)$t['is_active']));$runs=$pdo->query('SELECT r.*,t.name task_name FROM scheduled_task_runs r JOIN scheduled_tasks t ON t.id=r.task_id ORDER BY r.id DESC LIMIT 150')->fetchAll();View::render('scheduler',compact('user','tasks','runs','activeCount','error'));
    }
    private function taxQuote(PDO $pdo,int $userId,float $subtotal,string $currency):array
    {
        $country='';$s=$pdo->prepare('SELECT country FROM users WHERE id=:id');$s->execute(['id'=>$userId]);$country=strtoupper(trim((string)$s->fetchColumn()));
        $q=$pdo->prepare("SELECT id,rate FROM tax_rates WHERE is_active=1 AND (country IS NULL OR country='' OR country=:country) AND (currency IS NULL OR currency='' OR currency=:currency) ORDER BY CASE WHEN country=:country2 THEN 0 ELSE 1 END,CASE WHEN currency=:currency2 THEN 0 ELSE 1 END,priority ASC,id DESC LIMIT 1");
        $q->execute(['country'=>$country,'currency'=>$currency,'country2'=>$country,'currency2'=>$currency]);$tax=$q->fetch();$rate=$tax?round((float)$tax['rate'],4):0.0;$base=round($subtotal,2);$amount=round($base*$rate/100,2);
        return ['subtotal'=>$base,'tax_id'=>$tax?(int)$tax['id']:null,'tax_rate'=>$rate,'tax_amount'=>$amount,'total'=>round($base+$amount,2)];
    }
    private function deny():never{http_response_code(403);View::render('error',['title'=>'دسترسی غیرمجاز','message'=>'اجازه انجام این کار را ندارید.']);exit;}
    private function missing():never{http_response_code(404);View::render('error',['title'=>'پیدا نشد','message'=>'رکورد درخواستی وجود ندارد.']);exit;}
